package com.anonyser.digitalcompass;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;

/**
 * All of the compass drawing and the angle math, with no RuneLite dependencies.
 * The plugin overlay and the standalone preview both draw through this, so they look identical.
 */
public final class CompassRenderer
{
	private static final String[] CARDINALS = {"N", "NE", "E", "SE", "S", "SW", "W", "NW"};

	/** Plain drawing options (no RuneLite types). */
	public static final class Options
	{
		public int fontSize = 20;
		public boolean bold = true;
		public Color textColor = Color.WHITE;
		public boolean outline = true;
		public Color outlineColor = Color.BLACK;
		public boolean showRose = true;
		public boolean showCardinal = true;
		public int dial = 120;
	}

	private CompassRenderer()
	{
	}

	/** Jagex angle units (0-2047, 0 = south) to a compass bearing (north = 0, clockwise). */
	public static double jauToBearing(int units)
	{
		double deg = (units * 360.0) / 2048.0;
		return (deg + 180.0) % 360.0;
	}

	// Camera yaw is JAU14 (0-16383). It increases opposite to compass bearing, so negate it
	// to keep east and west on the correct sides (north/south are unaffected).
	public static double cameraYawToBearing(int yaw)
	{
		double deg = (yaw * 360.0) / 16384.0;
		return ((-deg) % 360.0 + 360.0) % 360.0;
	}

	/** Draws the compass at the current transform origin. Returns the space used. */
	public static Dimension draw(Graphics2D g, double bearing, Options o)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		bearing = ((bearing % 360) + 360) % 360;
		int shown = (int) Math.round(bearing) % 360;
		if (shown == 0)
		{
			shown = 360; // north reads as 360 per spec
		}

		int top = 0;
		if (o.showRose)
		{
			drawDial(g, bearing, o);
			top = o.dial;
		}
		int textHeight = drawReadout(g, shown, bearing, top, o);
		int width = o.showRose ? o.dial : Math.max(64, textHeight * 3);
		return new Dimension(width, top + textHeight + 4);
	}

	private static void drawDial(Graphics2D g, double bearing, Options o)
	{
		final int cx = o.dial / 2;
		final int cy = o.dial / 2;
		final int r = o.dial / 2 - 14;

		g.setColor(new Color(0, 0, 0, 140));
		g.fill(new Ellipse2D.Double(cx - r - 8, cy - r - 8, (r + 8) * 2, (r + 8) * 2));
		g.setColor(new Color(255, 255, 255, 90));
		g.setStroke(new BasicStroke(2f));
		g.draw(new Ellipse2D.Double(cx - r, cy - r, r * 2, r * 2));

		g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 12));
		drawCentered(g, "N", cx, cy - r + 4, Color.RED);
		drawCentered(g, "S", cx, cy + r - 4, Color.WHITE);
		drawCentered(g, "E", cx + r - 4, cy, Color.WHITE);
		drawCentered(g, "W", cx - r + 4, cy, Color.WHITE);

		final double rad = Math.toRadians(bearing);
		final int tipX = (int) Math.round(cx + Math.sin(rad) * (r - 8));
		final int tipY = (int) Math.round(cy - Math.cos(rad) * (r - 8));
		final double leftRad = rad + Math.toRadians(150);
		final double rightRad = rad - Math.toRadians(150);

		final Polygon arrow = new Polygon();
		arrow.addPoint(tipX, tipY);
		arrow.addPoint((int) Math.round(cx + Math.sin(leftRad) * 9), (int) Math.round(cy - Math.cos(leftRad) * 9));
		arrow.addPoint((int) Math.round(cx + Math.sin(rightRad) * 9), (int) Math.round(cy - Math.cos(rightRad) * 9));

		g.setColor(o.textColor);
		g.fill(arrow);
		g.setColor(new Color(0, 0, 0, 160));
		g.setStroke(new BasicStroke(1f));
		g.draw(arrow);
	}

	private static int drawReadout(Graphics2D g, int shown, double bearing, int top, Options o)
	{
		final int style = o.bold ? Font.BOLD : Font.PLAIN;
		g.setFont(new Font(Font.SANS_SERIF, style, o.fontSize));
		final FontMetrics fm = g.getFontMetrics();

		String text = shown + "°";
		if (o.showCardinal)
		{
			text += "  " + CARDINALS[(int) Math.round(bearing / 45.0) % 8];
		}

		final int x = 2;
		final int baseline = top + fm.getAscent();

		if (o.outline)
		{
			g.setColor(o.outlineColor);
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					if (dx != 0 || dy != 0)
					{
						g.drawString(text, x + dx, baseline + dy);
					}
				}
			}
		}

		g.setColor(o.textColor);
		g.drawString(text, x, baseline);
		return fm.getHeight();
	}

	private static void drawCentered(Graphics2D g, String s, int x, int y, Color c)
	{
		final FontMetrics fm = g.getFontMetrics();
		g.setColor(c);
		g.drawString(s, x - fm.stringWidth(s) / 2, y + fm.getAscent() / 2);
	}
}

package com.anonyser.digitalcompass;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("digitalcompass")
public interface DigitalCompassConfig extends Config
{
	enum DirectionSource
	{
		CAMERA,
		PLAYER
	}

	@ConfigItem(
		keyName = "directionSource",
		name = "Direction source",
		description = "Camera follows where you're looking; Player follows the way your character is facing.",
		position = 0
	)
	default DirectionSource directionSource()
	{
		return DirectionSource.CAMERA;
	}

	@Range(min = 8, max = 64)
	@ConfigItem(keyName = "fontSize", name = "Font size", description = "Size of the degree text.", position = 1)
	default int fontSize()
	{
		return 20;
	}

	@ConfigItem(keyName = "bold", name = "Bold text", description = "Draw the degree text in bold.", position = 2)
	default boolean bold()
	{
		return true;
	}

	@ConfigItem(keyName = "textColor", name = "Text colour", description = "Colour of the degree text and the facing arrow.", position = 3)
	default Color textColor()
	{
		return Color.WHITE;
	}

	@ConfigItem(keyName = "outline", name = "Text outline", description = "Draw an outline behind the text so it stays readable.", position = 4)
	default boolean outline()
	{
		return true;
	}

	@ConfigItem(keyName = "outlineColor", name = "Outline colour", description = "Colour of the text outline.", position = 5)
	default Color outlineColor()
	{
		return Color.BLACK;
	}

	@ConfigItem(keyName = "showRose", name = "Show compass dial", description = "Show the dial with N/E/S/W markers and a facing arrow.", position = 6)
	default boolean showRose()
	{
		return true;
	}

	@ConfigItem(keyName = "showCardinal", name = "Show cardinal label", description = "Show the nearest cardinal direction (N, NE, ...) next to the degrees.", position = 7)
	default boolean showCardinal()
	{
		return true;
	}

	@Range(min = -180, max = 180)
	@ConfigItem(keyName = "calibration", name = "Calibration offset", description = "Nudge the zero point if the reading looks rotated (degrees).", position = 8)
	default int calibration()
	{
		return 0;
	}

	@ConfigItem(keyName = "invert", name = "Reverse direction", description = "Flip the turn direction if it counts the wrong way.", position = 9)
	default boolean invert()
	{
		return false;
	}
}

package com.anonyser.digitalcompass;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class DigitalCompassOverlay extends Overlay
{
	private final Client client;
	private final DigitalCompassConfig config;

	@Inject
	DigitalCompassOverlay(Client client, DigitalCompassConfig config)
	{
		this.client = client;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setResizable(true);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		final Player local = client.getLocalPlayer();
		if (local == null)
		{
			return null;
		}

		double bearing = config.directionSource() == DigitalCompassConfig.DirectionSource.CAMERA
			? CompassRenderer.cameraYawToBearing(client.getCameraYaw())
			: CompassRenderer.jauToBearing(local.getOrientation());
		if (config.invert())
		{
			bearing = 360.0 - bearing;
		}
		bearing += config.calibration();

		final CompassRenderer.Options o = new CompassRenderer.Options();
		o.fontSize = config.fontSize();
		o.bold = config.bold();
		o.textColor = config.textColor();
		o.outline = config.outline();
		o.outlineColor = config.outlineColor();
		o.showRose = config.showRose();
		o.showCardinal = config.showCardinal();

		final Dimension pref = getPreferredSize();
		if (pref != null && pref.width > 0)
		{
			final double scale = Math.max(0.4, pref.width / (double) o.dial);
			g.scale(scale, scale);
			CompassRenderer.draw(g, bearing, o);
			return pref;
		}
		return CompassRenderer.draw(g, bearing, o);
	}
}

package com.anonyser.digitalcompass;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Digital Compass",
	description = "A clean on-screen compass that shows which way you are facing, in degrees",
	tags = {"compass", "direction", "overlay", "degrees", "digital"}
)
public class DigitalCompassPlugin extends Plugin
{
	@Inject
	private OverlayManager overlayManager;

	@Inject
	private DigitalCompassOverlay overlay;

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
	}

	@Provides
	DigitalCompassConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DigitalCompassConfig.class);
	}
}

package com.anonyser.digitalcompass;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class DigitalCompassPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(DigitalCompassPlugin.class);
		RuneLite.main(args);
	}
}
